import{_ as r,o as a,c as t,a2 as n}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Avec un agent","description":"","frontmatter":{"title":"Avec un agent"},"headers":[],"relativePath":"agent/index.md","filePath":"agent/index.md"}'),i={name:"agent/index.md"};function o(s,e,l,u,c,d){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="avec-un-agent" tabindex="-1">Avec un agent <a class="header-anchor" href="#avec-un-agent" aria-label="Permalink to &quot;Avec un agent&quot;">​</a></h1><p>Un agent branché sur Kessho est un assistant IA (Claude Code, Codex, Gemini CLI… voir <a href="/agent/connecter.html">Connecter l&#39;agent</a>) qui parle à votre mémoire par le serveur MCP de Kessho. Il y lit ce que vous avez déjà décidé, y écrit ce que la session apporte, et vous le retrouvez à l&#39;écran : l&#39;application et l&#39;agent regardent le <strong>même dossier</strong> de notes (voir <a href="/guide/vault.html">Choisir sa mémoire</a>).</p><h2 id="pourquoi" tabindex="-1">Pourquoi <a class="header-anchor" href="#pourquoi" aria-label="Permalink to &quot;Pourquoi&quot;">​</a></h2><p>Un assistant n&#39;a pas de mémoire d&#39;une session à l&#39;autre, ni d&#39;un outil à l&#39;autre. Avec Kessho, ce qui compte est écrit dans votre mémoire, un dossier de notes Markdown à vous : la session suivante, dans le même assistant ou dans un autre, repart de là sans que vous ayez à tout redire.</p><h2 id="le-cycle-reprendre-travailler-archiver" tabindex="-1">Le cycle : reprendre, travailler, archiver <a class="header-anchor" href="#le-cycle-reprendre-travailler-archiver" aria-label="Permalink to &quot;Le cycle : reprendre, travailler, archiver&quot;">​</a></h2><ol><li><strong>Reprendre.</strong> Vous dites « on reprend le projet X » ; l&#39;agent charge le contexte de ce projet. Voir <a href="/agent/reprendre.html">Reprendre un projet</a>.</li><li><strong>Travailler.</strong> Pendant la session, l&#39;agent peut chercher, noter une décision, ranger. Voir <a href="/agent/chercher.html">Chercher dans la mémoire</a> et <a href="/agent/ecrire.html">Écrire dans la mémoire</a>.</li><li><strong>Archiver.</strong> En fin de session, l&#39;agent écrit une archive datée et met à jour le contexte du projet. Voir <a href="/agent/archiver.html">Archiver une session</a>.</li></ol><h2 id="qui-fait-quoi" tabindex="-1">Qui fait quoi <a class="header-anchor" href="#qui-fait-quoi" aria-label="Permalink to &quot;Qui fait quoi&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Ce que fait</th><th>Où cela se voit</th></tr></thead><tbody><tr><td><strong>L&#39;application</strong> (Kessho)</td><td>Déclare son serveur chez vos assistants, dépose les procédures qui leur disent quand l&#39;appeler, affiche la mémoire, la synchronise en un clic.</td><td>Les écrans du <a href="/guide/">guide de l&#39;application</a>.</td></tr><tr><td><strong>L&#39;agent</strong></td><td>Appelle les outils MCP (les <code>mem_*</code>) : lire, chercher, écrire, ranger. Chaque outil est décrit dans la <a href="/reference/mcp/">Référence MCP</a>.</td><td>Le témoin de fraîcheur s&#39;allume quand il écrit (voir <a href="/guide/zones.html">Zones</a>).</td></tr></tbody></table><p>Chaque page de cette section part de ce que vous dites à l&#39;agent, puis explique ce que fait l&#39;agent (les outils appelés, ce qui change dans la mémoire), puis ce que montre l&#39;application.</p><h2 id="les-sept-parcours" tabindex="-1">Les sept parcours <a class="header-anchor" href="#les-sept-parcours" aria-label="Permalink to &quot;Les sept parcours&quot;">​</a></h2><ul><li><a href="/agent/connecter.html">Connecter l&#39;agent</a> : brancher votre assistant, et vérifier qu&#39;il voit Kessho.</li><li><a href="/agent/reprendre.html">Reprendre un projet</a> : retrouver où vous en étiez, sans rien re-expliquer.</li><li><a href="/agent/archiver.html">Archiver une session</a> : garder la trace d&#39;une session, et l&#39;annuler si besoin.</li><li><a href="/agent/chercher.html">Chercher dans la mémoire</a> : retrouver une décision, un fichier, une note.</li><li><a href="/agent/ecrire.html">Écrire dans la mémoire</a> : noter un fait, un principe, un objectif, une personne, un document.</li><li><a href="/agent/entretenir.html">Entretenir la mémoire</a> : contrôler la santé du dossier, renommer, déplacer, retirer.</li><li><a href="/agent/synchroniser.html">Synchroniser la mémoire</a> : garder la mémoire à jour entre vos postes, avec git.</li></ul><p>La liste complète des outils, avec leurs paramètres, est dans la <a href="/reference/mcp/">Référence MCP</a>.</p><h2 id="un-agent-ne-fait-pas-tout-seul" tabindex="-1">Un agent ne fait pas tout seul <a class="header-anchor" href="#un-agent-ne-fait-pas-tout-seul" aria-label="Permalink to &quot;Un agent ne fait pas tout seul&quot;">​</a></h2><p>Certains outils ne s&#39;exécutent qu&#39;à une condition, que chaque parcours rappelle : un essai à blanc avant d&#39;appliquer (<code>apply</code>, <code>confirm</code>), une confirmation motivée pour retirer une note. Ces garde-fous sont ceux du serveur, pas une politesse de l&#39;agent.</p><p>Une autre sorte de consigne n&#39;est pas vérifiée par le serveur : pour <code>mem_git_commit</code> et <code>mem_git_resolve</code>, c&#39;est la description de l&#39;outil qui demande à l&#39;agent l&#39;accord de l&#39;utilisateur ; le serveur, lui, ne le contrôle pas.</p>',15)])])}const m=r(i,[["render",o]]);export{p as __pageData,m as default};
